    @functools.lru_cache(maxsize=None)
    def lcs(i, j, k):
        if i == 0 or j == 0 or k == 0:
            return 0
        if s1[i-1] == s2[j-1] == s3[k-1]:
            return 1 + lcs(i-1, j-1, k-1)
        return max(lcs(i-1, j, k), lcs(i, j-1, k), lcs(i, j, k-1))
    return lcs(len(s1), len(s2), len(s3))

