import heapq

def large_product(list1, list2, n):
    list1.sort(reverse=True)
    list2.sort(reverse=True)
    max_heap = []
    visited = set()

    for i in range(len(list1)):
        for j in range(len(list2)):
            if (i, j) not in visited:
                product = list1[i] * list2[j]
                heapq.heappush(max_heap, (-product, i, j))
                visited.add((i, j))

    result = []
    for _ in range(n):
        if max_heap:
            neg_product, i, j = heapq.heappop(max_heap)
            result.append(-neg_product)
            if i + 1 < len(list1) and (i + 1, j) not in visited:
                product = list1[i + 1] * list2[j]
                heapq.heappush(max_heap, (-product, i + 1, j))
                visited.add((i + 1, j))
            if j + 1 < len(list2) and (i, j + 1) not in visited:
                product = list1[i] * list2[j + 1]
                heapq.heappush(max_heap, (-product, i, j + 1))
                visited.add((i, j + 1))
    return result

import heapq

def large_product(list1, list2, n):
    list1.sort(reverse=True)
    list2.sort(reverse=True)
    max_heap = []
    visited = set()

    for i in range(len(list1)):
        for j in range(len(list2)):
            if (i, j) in visited:
                continue
            product = list1[i] * list2[j]
            heapq.heappush(max_heap, -product)
            visited.add((i, j))
            if len(max_heap) > n:
                heapq.heappop(max_heap)

    return [-x for x in max_heap]

